/// Validate typed owner before entering the lower planner and require its entire
/// computed pattern mapping at return. This performs no legacy owned conversion.
/// The lower adapter owns/admit/releases its plan/cache allocations via ctx.ledger.
pub fn plan_production_definition<'src>(
    planner: &mut dyn DefinitionPlanner,
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    owner.validate(ctx)?;
    validate_style(ctx.shared.source(), style, control)?;
    ctx.shared
        .element(element, crate::memory::add(element.0, 1)?, control)?;
    if !vexel_geometry::affine_valid(transform)
        || !bounds.into_iter().all(f64::is_finite)
        || bounds[2] < 0.
        || bounds[3] < 0.
    {
        return Err(invalid(0));
    }
    let plan = planner
        .plan_owned_definition(ctx, kind, element, owner, transform, bounds, style, control)?;
    let (definition, mapping) = match &plan {
        ProductionDefinitionPlan::Definition(plan) => (plan, None),
        ProductionDefinitionPlan::Pattern { plan, mapping } => (plan, Some(*mapping)),
    };
    let actual = match &definition.descriptor {
        DefinitionDescriptor::Clip(_) => DefinitionKind::Clip,
        DefinitionDescriptor::Mask(_) => DefinitionKind::Mask,
        DefinitionDescriptor::Pattern(descriptor) => {
            if descriptor.definition != element {
                return Err(invalid(0));
            }
            let map = mapping.ok_or_else(|| invalid(0))?;
            map.pixel_inverse(*descriptor)?;
            let DefinitionTarget::Shape(shape) = owner.target else {
                return Err(invalid(0));
            };
            if ctx
                .builder
                .scene(ctx.scene)?
                .shape(shape)
                .ok_or_else(|| invalid(0))?
                .source
                != map.source_map
                || map.bounds != bounds
            {
                return Err(invalid(0));
            }
            DefinitionKind::Pattern
        }
        DefinitionDescriptor::Marker(_) => DefinitionKind::Marker,
        DefinitionDescriptor::Filter { filter, primitives } => {
            let DefinitionTarget::Group(_) = owner.target else {
                return Err(invalid(0));
            };
            crate::validate::filter(*filter, primitives, control)?;
            for p in primitives {
                control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
                if p.source_offset > ctx.shared.source().len() {
                    return Err(invalid(p.source_offset));
                }
            }
            DefinitionKind::Filter
        }
    };
    if actual != kind || (kind != DefinitionKind::Pattern && mapping.is_some()) {
        return Err(invalid(0));
    }
    crate::mask_post::validate_production_post(ctx, kind, None, definition.post, control)?;
    if definition.expansions.len() > 65536 {
        return Err(crate::types::limit(LimitKind::References));
    }
    for expansion in &definition.expansions {
        crate::mask_post::validate_production_post(
            ctx,
            kind,
            Some(expansion.flavor),
            expansion.post,
            control,
        )?;
        control
            .charge(WorkKind::ReferenceProbe, 1)
            .map_err(stopped)?;
        expansion.range.require(ctx.shared.tokens().len(), 0)?;
        validate_style(ctx.shared.source(), &expansion.style, control)?;
        if !vexel_geometry::affine_valid(expansion.transform)
            || !expansion
                .viewport
                .into_iter()
                .all(|v| v.is_finite() && v > 0.)
        {
            return Err(invalid(0));
        }
    }
    control.checkpoint().map_err(stopped)?;
    Ok(plan)
}

fn validate_style(
    source: &[u8],
    style: &CssPaint<'_>,
    control: &mut dyn WorkControl,
) -> Result<()> {
    for property in vexel_svg_css::Property::ALL {
        control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
        if let Some(value) = style.value(property) {
            let bytes = value
                .span
                .slice(source)
                .ok_or_else(|| invalid(value.span.offset))?;
            if bytes.as_ptr() != value.bytes.as_ptr() || bytes.len() != value.bytes.len() {
                return Err(invalid(value.span.offset));
            }
        }
    }
    Ok(())
}
//! Soft scheduling boundary between bounded synchronous operations. This is not
//! interruption/resumption inside an operation and promises no main-thread latency.
use crate::{types::invalid, *};
#[derive(Debug, PartialEq, Eq)]
pub enum AtomicStep<T, P = ()> {
    Complete(T),
    Boundary(P),
}
/// One step's cumulative actual work, including atomic overshoot and failed calls.
/// Once at the boundary, no further operation starts. A new quantum continues
/// from the caller's retained engine state, never replays a completed operation.
pub struct DecodeQuantum {
    requested: u64,
    work: RenderWorkStats,
}
impl DecodeQuantum {
    pub fn new(requested: u64) -> Result<Self> {
        if requested == 0 {
            return Err(invalid(0));
        }
        Ok(Self {
            requested,
            work: RenderWorkStats::default(),
        })
    }
    pub fn work(&self) -> RenderWorkStats {
        self.work
    }
    pub fn overshoot(&self) -> u64 {
        self.work.total_work.saturating_sub(self.requested)
    }
    /// Exactly one existing bounded shared atomic operation per call. Lower
    /// adapters must use their own original bounded atomic primitive and pass
    /// this control to every actual loop. No invented token-only progress.
    pub fn atomic<T>(
        &mut self,
        control: &mut dyn WorkControl,
        operation: impl FnOnce(&mut dyn WorkControl) -> Result<T>,
    ) -> Result<AtomicStep<T>> {
        if self.work.total_work >= self.requested {
            return Ok(AtomicStep::Boundary(()));
        }
        let mut meter = QuantumControl {
            work: &mut self.work,
            inner: control,
        };
        meter.checkpoint().map_err(crate::types::stopped)?;
        operation(&mut meter).map(AtomicStep::Complete)
    }
    pub fn compute_style<'src>(
        &mut self,
        source: &mut DecodeSource<'src>,
        element: ElementId,
        parent: Option<&CssPaint<'src>>,
        control: &mut dyn WorkControl,
    ) -> Result<AtomicStep<CssPaint<'src>>> {
        self.atomic(control, |c| source.compute_style(element, parent, c))
    }
    pub fn find_reference(
        &mut self,
        source: &mut DecodeSource<'_>,
        value: vexel_xml::XmlSpan,
        control: &mut dyn WorkControl,
    ) -> Result<AtomicStep<Option<ElementId>>> {
        self.atomic(control, |c| source.find_reference(value, c))
    }
    pub fn append_shape(
        &mut self,
        builder: &mut SceneBuilder,
        scene: SceneId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<AtomicStep<ShapeId, ShapeInput>> {
        if self.work.total_work >= self.requested {
            return Ok(AtomicStep::Boundary(input));
        }
        let mut meter = QuantumControl {
            work: &mut self.work,
            inner: control,
        };
        meter.checkpoint().map_err(crate::types::stopped)?;
        builder
            .append_shape(scene, input, &mut meter)
            .map(AtomicStep::Complete)
    }
    pub fn commit_request(
        &mut self,
        builder: &mut SceneBuilder,
        draft: &DraftToken,
        request: RequestToken,
        control: &mut dyn WorkControl,
    ) -> Result<AtomicStep<()>> {
        self.atomic(control, |c| builder.commit_request(draft, request, c))
    }
    pub fn commit_draft(
        &mut self,
        builder: &mut SceneBuilder,
        draft: &DraftToken,
        control: &mut dyn WorkControl,
    ) -> Result<AtomicStep<()>> {
        self.atomic(control, |c| builder.commit_draft(draft, c))
    }
}
struct QuantumControl<'a> {
    work: &'a mut RenderWorkStats,
    inner: &'a mut dyn WorkControl,
}
impl WorkControl for QuantumControl<'_> {
    fn charge(&mut self, kind: WorkKind, units: u64) -> std::result::Result<(), Stop> {
        // Count reported work at the same call site even if the outer policy stops.
        // Overflow is detected before a provider can perform unreportable work.
        self.work.charge(kind, units).map_err(|_| Stop::Overflow)?;
        self.inner.charge(kind, units)
    }
    fn checkpoint(&mut self) -> std::result::Result<(), Stop> {
        self.inner.checkpoint()
    }
}
//! Explicit owning clients of the accepted ledger allocator. No Vec/lease escape.
//! Drop without release conservatively retains the charge until ledger teardown.
//! Clients must release before discarding; replacements count as a second active
//! record, so a query ledger configured for 65536 enforces overlap at that limit.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LedgerIdentity(u64);
#[derive(Debug)]
pub struct LedgerBuffer<T: Copy> {
    values: Option<Vec<T>>,
    lease: AllocationLease,
}
impl ChargeLedger {
    pub fn owner_identity(&self) -> LedgerIdentity {
        LedgerIdentity(self.identity())
    }
    pub fn require_owner(&self, identity: LedgerIdentity, source: &SourceOwner) -> Result<()> {
        if identity != self.owner_identity() || !std::sync::Arc::ptr_eq(source, self.source_owner())
        {
            return Err(invalid(0));
        }
        Ok(())
    }
    /// Requested reservation precedes physical reserve; actual capacity is
    /// admitted before return. Successful physical history survives cancellation.
    pub fn allocate_buffer<T: Copy>(
        &mut self,
        tag: AllocationTag,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<LedgerBuffer<T>> {
        let (values, lease) = self.allocate(tag, capacity, control)?;
        Ok(LedgerBuffer {
            values: Some(values),
            lease,
        })
    }
    pub(crate) fn require_lease(&self, lease: AllocationLease) -> Result<()> {
        // Defined alongside private registry access in accounting.rs.
        self.check_lease(lease)
    }
}
impl<T: Copy> LedgerBuffer<T> {
    fn require(&self, ledger: &ChargeLedger) -> Result<()> {
        if self.values.is_none() {
            return Err(invalid(0));
        }
        ledger.require_lease(self.lease)
    }
    pub fn values<'a>(&'a self, ledger: &ChargeLedger) -> Result<&'a [T]> {
        self.require(ledger)?;
        Ok(self.values.as_ref().ok_or_else(|| invalid(0))?)
    }
    pub fn values_mut<'a>(&'a mut self, ledger: &ChargeLedger) -> Result<&'a mut [T]> {
        self.require(ledger)?;
        Ok(self.values.as_mut().ok_or_else(|| invalid(0))?)
    }
    pub fn capacity(&self, ledger: &ChargeLedger) -> Result<usize> {
        self.require(ledger)?;
        Ok(self.values.as_ref().ok_or_else(|| invalid(0))?.capacity())
    }
    /// No allocation. Poll every real iteration; unpublished suffix is removed
    /// on cancellation, preserving the old values and admitted capacity.
    pub fn append(
        &mut self,
        ledger: &ChargeLedger,
        suffix: &[T],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(ledger)?;
        control.checkpoint().map_err(stopped)?;
        let values = self.values.as_mut().ok_or_else(|| invalid(0))?;
        let len = values.len();
        let end = len
            .checked_add(suffix.len())
            .ok_or_else(crate::memory::arithmetic)?;
        if end > values.capacity() {
            return Err(invalid(0));
        }
        let result = (|| {
            for value in suffix {
                control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
                values.push(*value);
            }
            control.checkpoint().map_err(stopped)
        })();
        if result.is_err() {
            values.truncate(len);
        }
        result
    }
    /// Reserve old+new overlap, then controlled copy, then drop old storage before
    /// releasing its charge. Errors leave old data/token/capacity unchanged.
    pub fn replace_capacity(
        &mut self,
        ledger: &mut ChargeLedger,
        tag: AllocationTag,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(ledger)?;
        if capacity < self.values(ledger)?.len() {
            return Err(invalid(0));
        }
        let mut replacement = ledger.allocate_buffer(tag, capacity, control)?;
        if let Err(error) = replacement.append(ledger, self.values(ledger)?, control) {
            replacement.release(ledger)?;
            return Err(error);
        }
        self.release(ledger)?;
        *self = replacement;
        Ok(())
    }
    pub fn truncate(&mut self, ledger: &ChargeLedger, len: usize) -> Result<()> {
        self.require(ledger)?;
        self.values
            .as_mut()
            .ok_or_else(|| invalid(0))?
            .truncate(len);
        Ok(())
    }
    /// Unconditional after cancellation, checked stale/double/foreign access.
    pub fn release(&mut self, ledger: &mut ChargeLedger) -> Result<()> {
        self.require(ledger)?;
        drop(self.values.take());
        ledger.release(self.lease)
    }
}
//! Complete computed plan handoff. Mapping is carried at suspension, never
//! reconstructed by parsing source on resume. Original descriptors stay intact.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PatternMapping {
    pub tile_origin: [f64; 2],
    pub user_to_base: Affine,
    pub pattern_transform: Affine,
    pub user_inverse: Affine,
    pub viewport: [f64; 2],
    pub bounds: [f64; 4],
    pub source_map: SourceMap,
    pub opacity: f64,
}
impl PatternMapping {
    pub fn pixel_inverse(self, descriptor: PatternDescriptor) -> Result<Affine> {
        use vexel_geometry::{affine_compose, affine_valid};
        if !self.tile_origin.into_iter().all(f64::is_finite)
            || !self.viewport.into_iter().all(|v| v.is_finite() && v > 0.)
            || !self.bounds.into_iter().all(f64::is_finite)
            || self.bounds[2] < 0.
            || self.bounds[3] < 0.
            || !self.opacity.is_finite()
            || !(0.0..=1.0).contains(&self.opacity)
            || !affine_valid(self.user_inverse)
            || !affine_valid(self.source_map.transform)
        {
            return Err(invalid(descriptor.error_offset));
        }
        // The supplied computed inverse must implement inverse(patternTransform)
        // followed by translation(-tileOrigin), as in the original algorithm.
        let back = affine_compose(self.user_to_base, self.pattern_transform)
            .ok_or_else(|| invalid(descriptor.error_offset))?;
        let expected = [1., 0., 0., 1., -self.tile_origin[0], -self.tile_origin[1]];
        for (a, b) in [back.a, back.b, back.c, back.d, back.e, back.f]
            .into_iter()
            .zip(expected)
        {
            if (a - b).abs() > 1e-9 * a.abs().max(b.abs()).max(1.) {
                return Err(invalid(descriptor.error_offset));
            }
        }
        let scale = Affine {
            a: descriptor.width as f64 / descriptor.tile_width,
            d: descriptor.height as f64 / descriptor.tile_height,
            b: 0.,
            c: 0.,
            e: 0.,
            f: 0.,
        };
        affine_compose(scale, self.user_to_base).ok_or_else(|| invalid(descriptor.error_offset))
    }
}
#[derive(Debug, Clone, Copy)]
pub(crate) struct PatternContinuation {
    mapping: PatternMapping,
    parent: SceneId,
    shape: ShapeId,
    channel: PaintChannel,
    draft: u64,
    generation: u64,
    request: Option<RequestToken>,
    job: LedgerIdentity,
}
impl PatternTickets {
    pub fn request_mapped<'a>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a>> {
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, shape.index(), builder.scenes[i].shapes.len())?;
        job.validate_source(builder.source_owner())?;
        if !std::sync::Arc::ptr_eq(builder.source_owner(), source.source_owner()) {
            return Err(invalid(0));
        }
        let definition = source.element(
            descriptor.definition,
            crate::memory::add(descriptor.definition.0, 1)?,
            control,
        )?;
