    /// The caller retains the actual render job across pattern suspensions.
    pub fn step_production<'s>(&'s mut self, work_quantum: u64, operations: &mut dyn ProductionDecodeOperations, job: &RasterJob, control: &mut dyn WorkControl) -> Result<DecodeEvent<'s>> {
        job.validate_source(self.shared.source_owner())?;
        self.step_internal(work_quantum,&mut crate::operations::Operations::Production(operations),Some(job),control)
    }
    fn step_internal(&mut self, work_quantum: u64, operations: &mut crate::operations::Operations<'_>, job: Option<&RasterJob>, control: &mut dyn WorkControl) -> Result<DecodeEvent<'_>> {
        if self.state == DecoderState::Failed {
            return Err(invalid(0));
        }
        if self.state == DecoderState::Complete {
            return Ok(DecodeEvent::Complete);
        }
        if work_quantum == 0 {
            return Err(invalid(0));
        }
        if let Some(pending) = &self.pending_pattern {
            let offset = pending.descriptor.error_offset;
            if pending.offered {
                return Err(self.abort(invalid(offset)));
            }
            control
                .checkpoint()
                .map_err(|s| self.abort(crate::source::stopped(s, offset)))?;
            return self.pattern_event(job,control);
        }
        let mut tally = Tally {
            inner: control,
            charged: 0,
        };
        while tally.charged < work_quantum {
            let Some(task) = self.tasks.pop() else {
                self.ignored
                    .publish(self.builder.as_mut().ok_or_else(|| invalid(0))?, &mut tally)
                    .map_err(|e| self.abort(e))?;
                if !self.root_seen {
                    return Err(self.abort(Diagnostic {
                        kind: ErrorKind::Viewport,
                        offset: 0,
                    }));
                }
                self.state = DecoderState::Complete;
                return Ok(DecodeEvent::Complete);
            };
            if let Err(e) = self.process(task, operations, &mut tally) {
                return Err(self.abort(e));
            }
            if let Some(pending) = &self.pending_pattern {
                let offset = pending.descriptor.error_offset;
                tally
                    .checkpoint()
                    .map_err(|s| self.abort(crate::source::stopped(s, offset)))?;
                return self.pattern_event(job,&mut tally);
            }
        }
        Ok(DecodeEvent::Progress {
            charged_units: tally.charged,
        })
    }
    pub(crate) fn abort(&mut self, error: Diagnostic) -> Diagnostic {
        self.tasks.clear();
        self.tickets.cancel();
        self.pending_pattern = None;
        while let Some((_, token)) = self.child_drafts.pop() {
            if let Some(builder) = self.builder.as_mut() {
                let _ = builder.rollback_draft(token);
            }
        }
        self.active.uses.clear();
        if let (Some(b), Some(t)) = (self.builder.as_mut(), self.draft.take()) {
            let _ = b.rollback_draft(t);
        }
        self.state = DecoderState::Failed;
        error
    }
    fn pattern_event(&mut self, job: Option<&RasterJob>, control: &mut dyn WorkControl) -> Result<DecodeEvent<'_>> {
        let pending = self
            .pending_pattern
            .as_mut()
        Decoder::finish(self, c)
    }
