        if let Err(s)=control.charge(WorkKind::SourceRead,1){drop(next);ledger.release(charge)?;return Err(crate::source::stopped(s,0));}
        next.push(value);
    }
    *values=next;
    if let Some(old)=lease.replace(charge){ledger.release(old)?;}
    Ok(())
}
