 let m=affine_compose(left,right).unwrap();assert_eq!(affine_map_point(m,Point {x:1.,y:2.}).unwrap(),Point {x:12.,y:26.});
 let p=affine_map_point(Affine {a:0.,b:0.,c:0.,d:0.,e:1.,f:1.},Point {x:3.,y:4.}).unwrap();assert_eq!(p,Point{x:1.,y:1.});assert!(affine_compose(Affine {a:f64::NAN,..left},left).is_none());
